params.command:
$ErrorActionPreference='Stop';
Write-Output ('HEAD='+(git rev-parse HEAD));
Write-Output '=== MATCHES ===';
git grep -n -E "assertWorkerPlacement|approve-for-me|deployOne|worker provider|workerProvider|remote worker|heaven-bridge|HEAVEN" -- tools/agent-control;
Write-Output '=== SERVER CONTEXT ===';
$path='tools\agent-control\server.mjs';
$lines=Get-Content $path;
$need=@();
for($i=0;$i -lt $lines.Count;$i++){if($lines[$i] -match 'assertWorkerPlacement|approve-for-me|function deployOne|async function deployOne'){ $need += $i }}
foreach($n in $need){$a=[Math]::Max(0,$n-35);$b=[Math]::Min($lines.Count-1,$n+90);Write-Output ("--- lines {0}-{1} ---" -f ($a+1),($b+1));$lines[$a..$b]};
Write-Output '=== PACKAGE ==='; Get-Content tools\agent-control\package.json;
Write-Output '=== TEST FILES ==='; Get-ChildItem tools\agent-control\test | Select-Object Name,Length | Format-Table -AutoSize
